#include <iostream>
#include <vector>
#include <set>
#include <map>
#include <string>
#include <utility>
// 공백으로 나눈 토큰 전체를 검사합니다. 숫자 사이의 붙은 부호는 허용하지 않습니다.
template <typename T>
bool ReadInteger(T& result, long long low, long long high) {
    std::string token;
    if (!(std::cin >> token)) return false;
    std::size_t pos = 0;
    bool negative = false;
    if (token[pos] == '+' || token[pos] == '-') {
        negative = token[pos] == '-';
        if (++pos == token.size()) return false;
    }
    const long long bound = (-low > high) ? -low : high;
    long long magnitude = 0;
    for (; pos < token.size(); ++pos) {
        if (token[pos] < '0' || token[pos] > '9') return false;
        const int digit = token[pos] - '0';
        if (digit > bound || magnitude > (bound - digit) / 10) return false;
        magnitude = magnitude * 10 + digit;
    }
    const long long value = negative ? -magnitude : magnitude;
    if (value < low || value > high) return false;
    result = static_cast<T>(value);
    return true;
}
int main(){
    int n; if(!ReadInteger(n,0,50)) return 1;
    std::vector<int> sizes(n,0);
    std::map<int,std::vector<int> > posting;
    for(int id=0;id<n;++id){
        int k; if(!ReadInteger(k,0,100)) return 1;
        std::set<int> unique;
        for(int j=0;j<k;++j){int x;if(!ReadInteger(x,0,10000))return 1;unique.insert(x);}
        sizes[id]=static_cast<int>(unique.size());
        // 같은 문서의 중복 단어는 한 번만 색인에 넣습니다.
        for(std::set<int>::const_iterator it=unique.begin();it!=unique.end();++it) posting[*it].push_back(id);
    }
    std::string extra; if(std::cin>>extra) return 1;
    std::map<std::pair<int,int>,int> intersections;
    for(std::map<int,std::vector<int> >::const_iterator it=posting.begin();it!=posting.end();++it){
        const std::vector<int>& ids=it->second;
        for(std::size_t a=0;a<ids.size();++a) for(std::size_t b=a+1;b<ids.size();++b)
            ++intersections[std::make_pair(ids[a],ids[b])];
    }
    // 양수인 쌍만 ID 오름차순으로 출력합니다. 분수는 약분하지 않습니다.
    for(std::map<std::pair<int,int>,int>::const_iterator it=intersections.begin();it!=intersections.end();++it){
        int a=it->first.first,b=it->first.second,c=it->second;
        std::cout<<a<<' '<<b<<' '<<c<<' '<<sizes[a]+sizes[b]-c<<'\n';
    }
}
